CREATE OR ALTER VIEW gold.reservoir_daily AS
WITH candidates AS (
    SELECT
        s.station_id,
        s.reading_date,
        s.storage_af,
        s.data_flag,
        s.is_missing,
        s.is_estimated,
        s.is_revised,
        s.run_id,
        s.ingested_at,
        ROW_NUMBER() OVER (
            PARTITION BY s.station_id, s.reading_date
            ORDER BY s.is_missing ASC, s.ingested_at DESC, s.run_id DESC
        ) AS rn
    FROM OPENROWSET(BULK 'silver/reservoir_storage/*/*.parquet', DATA_SOURCE = 'lake', FORMAT = 'PARQUET') AS s
    WHERE s.is_header = 0 AND s.reject_reason IS NULL
)
SELECT
    c.station_id,
    ref.station_name,
    c.reading_date,
    c.storage_af,
    ref.capacity_af,
    CASE
        WHEN c.storage_af IS NULL THEN NULL
        ELSE ROUND(100.0 * c.storage_af / ref.capacity_af, 1)
    END AS pct_capacity,
    c.is_missing,
    c.is_estimated,
    c.is_revised,
    c.data_flag,
    c.run_id AS source_run_id,
    c.ingested_at
FROM candidates AS c
INNER JOIN OPENROWSET(BULK 'reference/stations.csv', DATA_SOURCE = 'lake', FORMAT = 'CSV', PARSER_VERSION = '2.0', HEADER_ROW = TRUE) WITH (station_id VARCHAR(10) COLLATE Latin1_General_100_BIN2_UTF8, station_name VARCHAR(100) COLLATE Latin1_General_100_BIN2_UTF8, capacity_af BIGINT) AS ref
    ON ref.station_id = c.station_id
WHERE c.rn = 1;
GO

CREATE OR ALTER VIEW gold.reservoir_latest AS
WITH d AS (
    SELECT * FROM gold.reservoir_daily AS x
),
last_obs AS (
    SELECT station_id, MAX(reading_date) AS latest_date
    FROM d
    WHERE storage_af IS NOT NULL
    GROUP BY station_id
),
as_of AS (
    SELECT MAX(reading_date) AS as_of_date FROM d
)
SELECT
    d.station_id,
    d.station_name,
    d.reading_date AS latest_date,
    d.storage_af,
    d.capacity_af,
    d.pct_capacity,
    d.is_estimated,
    wk.storage_af AS storage_af_7d_ago,
    CASE
        WHEN wk.storage_af IS NULL THEN NULL
        ELSE d.storage_af - wk.storage_af
    END AS change_7d_af,
    DATEDIFF(day, d.reading_date, a.as_of_date) AS days_behind
FROM d
INNER JOIN last_obs AS l
    ON l.station_id = d.station_id AND l.latest_date = d.reading_date
CROSS JOIN as_of AS a
LEFT JOIN d AS wk
    ON wk.station_id = d.station_id
    AND wk.reading_date = DATEADD(day, -7, d.reading_date);
GO

CREATE OR ALTER VIEW gold.statewide_daily AS
SELECT
    d.reading_date,
    COUNT(*) AS stations_in_feed,
    SUM(CASE WHEN d.storage_af IS NOT NULL THEN 1 ELSE 0 END) AS stations_reporting,
    CASE
        WHEN COUNT(*) = SUM(CASE WHEN d.storage_af IS NOT NULL THEN 1 ELSE 0 END)
        THEN SUM(d.storage_af)
        ELSE NULL
    END AS total_storage_af,
    SUM(d.storage_af) AS partial_storage_af,
    CASE
        WHEN COUNT(*) = SUM(CASE WHEN d.storage_af IS NOT NULL THEN 1 ELSE 0 END)
        THEN ROUND(100.0 * SUM(d.storage_af) / SUM(d.capacity_af), 1)
        ELSE NULL
    END AS pct_capacity
FROM gold.reservoir_daily AS d
GROUP BY d.reading_date;
GO

CREATE OR ALTER VIEW gold.revisions AS
SELECT
    s.station_id,
    s.reading_date,
    COUNT(DISTINCT s.run_id) AS runs_seen,
    COUNT(DISTINCT COALESCE(CAST(s.storage_af AS VARCHAR(20)), 'missing')) AS distinct_values,
    MIN(s.storage_af) AS min_storage_af,
    MAX(s.storage_af) AS max_storage_af
FROM OPENROWSET(BULK 'silver/reservoir_storage/*/*.parquet', DATA_SOURCE = 'lake', FORMAT = 'PARQUET') AS s
WHERE s.is_header = 0 AND s.reject_reason IS NULL
GROUP BY s.station_id, s.reading_date
HAVING COUNT(DISTINCT COALESCE(CAST(s.storage_af AS VARCHAR(20)), 'missing')) > 1;
GO

CREATE OR ALTER VIEW gold.quarantine AS
SELECT
    s.station_id,
    s.reading_date,
    s.storage_af,
    s.data_flag,
    s.reject_reason,
    s.run_id,
    s.ingested_at
FROM OPENROWSET(BULK 'silver/reservoir_storage/*/*.parquet', DATA_SOURCE = 'lake', FORMAT = 'PARQUET') AS s
WHERE s.is_header = 0 AND s.reject_reason IS NOT NULL;
GO
